-- Autostart Configuration
-- Machine-specific startup apps go in autostart.local.conf

-- EWW dashboard animations (fast)
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.animation({
    leaf = "layersIn",
    enabled = true,
    speed = 1,
    bezier = "default",
    style = "slide",
})
hl.animation({
    leaf = "layersOut",
    enabled = true,
    speed = 1,
    bezier = "default",
    style = "slide",
})

-- Universal exec-once commands

-- Universal keybinds
hl.bind("SUPER + D", hl.dsp.exec_cmd("syna-dashboard-toggle"))

-- Source machine-specific autostart config
-- Source: ~/.config/hypr/autostart.local.conf — convert this file to Lua and ensure it is on Lua's package.path.
syna_optional(os.getenv("HOME") .. "/.config/hypr/autostart.local")  -- machine-local, not in git

hl.on("hyprland.start", function()
    hl.exec_cmd("syna-eww-init")
    hl.exec_cmd("syna-dashboard-focus-watcher")
    hl.exec_cmd("syna-audio-opacity-daemon")
end)

